"""Write a requirements file whose every line carries the PyPI SHA-256 hashes.

Input: requirement specifiers (``build==1.6.1 setuptools==84.0.0 ...``) and
an output path. Run with the interpreter the workflow installs into (3.11):

    python3.11 .github/ci/hashed_requirements.py \\
        .github/ci/release-requirements.txt \\
        pip==26.2.1 build==1.6.1 setuptools==84.0.0 wheel==0.48.0

A release uploaded in the last 7 days is not taken
(``pip --uploaded-prior-to P7D``), the cooldown .github/dependabot.yml
gives every other update: a release retracted or found compromised within
days of publication never reaches the file.

Output: the file, one ``name==version`` per distribution of the resolved
closure followed by one ``--hash=sha256:...`` per file PyPI publishes for
that release (every wheel and the sdist), sorted by name, with a header
that repeats the command. ``pip install --require-hashes -r FILE`` then
installs exactly these releases and refuses any byte that differs from
what PyPI published when the file was written.

Semantics: the closure is pip's own resolution
(``pip install --dry-run --ignore-installed --report``) on this
interpreter, so environment markers are evaluated for it; the hashes come
from the PyPI JSON API (``/pypi/<name>/<version>/json``, ``digests.sha256``)
for every file of the release, so the file holds on any platform the
release has a wheel for, not only the one that ran this.

Rejected alternatives:
- ``pip-compile --generate-hashes`` (pip-tools): a tool of its own to pin
  and install before the file that pins tools can be written; this script
  needs pip and the standard library only.
- the hashes in pip's report (``download_info.archive_info.hashes``): one
  file per release, the one this machine would download, so a wheel for
  another platform or Python would be refused.

Cost: one dry-run resolution and one HTTPS request per distribution,
measured 2026-10-16: release-requirements.txt (6 distributions) in 1 s,
sbom-requirements.txt (33) in 3 s.
"""

from __future__ import annotations

import json
import subprocess
import sys
import tempfile
import urllib.request
from pathlib import Path

_PYPI = "https://pypi.org/pypi/{name}/{version}/json"
_COOLDOWN = "P7D"


def resolve(requirements: list[str]) -> list[tuple[str, str]]:
    """(name, version) of every distribution pip would install, sorted."""
    with tempfile.TemporaryDirectory() as tmp:
        report = Path(tmp) / "report.json"
        subprocess.run(
            [sys.executable, "-m", "pip", "install", "--dry-run",
             "--ignore-installed", "--quiet", "--report", str(report),
             "--uploaded-prior-to", _COOLDOWN,
             *requirements],
            check=True)
        data = json.loads(report.read_text(encoding="utf-8"))
    found = {(item["metadata"]["name"].lower().replace("_", "-"),
              item["metadata"]["version"]) for item in data["install"]}
    return sorted(found)


def release_hashes(name: str, version: str, fetch=None) -> list[str]:
    """SHA-256 of every file PyPI publishes for ``name==version``, sorted."""
    if fetch is None:
        def fetch(url: str) -> dict:
            with urllib.request.urlopen(url, timeout=60) as answer:
                return json.loads(answer.read().decode("utf-8"))
    payload = fetch(_PYPI.format(name=name, version=version))
    hashes = sorted({str(f["digests"]["sha256"]) for f in payload.get("urls") or []})
    if not hashes:
        raise SystemExit(f"{name}=={version}: PyPI lists no files")
    return hashes


def render(pins: list[tuple[str, str, list[str]]], command: str) -> str:
    lines = [
        "# Generated by .github/ci/hashed_requirements.py; do not edit by hand.",
        "# Regenerate after changing a version (Python 3.11):",
        f"#   {command}",
        "# Installed with: pip install --require-hashes -r <this file>",
        "",
    ]
    for name, version, hashes in pins:
        lines.append(f"{name}=={version} \\")
        for index, digest in enumerate(hashes):
            tail = " \\" if index < len(hashes) - 1 else ""
            lines.append(f"    --hash=sha256:{digest}{tail}")
    return "\n".join(lines) + "\n"


def main(argv: list[str]) -> int:
    if len(argv) < 2:
        print(__doc__, file=sys.stderr)
        return 2
    out, requirements = Path(argv[0]), argv[1:]
    pins = [(name, version, release_hashes(name, version))
            for name, version in resolve(requirements)]
    command = "python3.11 .github/ci/hashed_requirements.py " + " ".join(argv)
    out.write_text(render(pins, command), encoding="utf-8")
    print(f"{out}: {len(pins)} distributions")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
